"use strict";(globalThis.webpackChunkmy_website||=[]).push([[10509],{41194(e){e.exports=JSON.parse('{"slug":"soft-fork","title":"Soft Fork","short":"A protocol upgrade that is backward-compatible, so nodes running older software can still follow the chain; they just don\'t see the new feature.","category":"network","aliases":[],"mentalModel":"A backwards-compatible upgrade. Old node software can still follow the chain; it just doesn\'t get the new feature.","related":["hard-fork"],"sources":[],"link":null,"level":"beginner","body":"In contrast to a hard fork, a soft fork tightens existing rules rather than introducing new ones, which is what lets unupgraded nodes keep validating without splitting off."}')}}]);